#!/usr/bin/env bash
# Hourly disk usage report -> logs/disk.log
set -euo pipefail

LOG=/workspace/logs/disk.log
: > "$LOG"

df -hP | awk '
NR==1 { next }
{
  split($NF, dev, "/");
  if (dev[1] == "host") {
    print "HOST\t" $0;
    next;
  }
  print "LOCAL\t" $0;
}'

args.command:
docker exec -it app bash -c "
psql -U postgres -d app_db -c '
DROP TABLE IF EXISTS users;
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL,
    age INT NOT NULL,
    city VARCHAR(50) DEFAULT 'Shanghai'
);
ALTER TABLE users ADD CONSTRAINT fk_users_city FOREIGN KEY (city) DEFAULT 'Shanghai';
CREATE TRIGGER trigger_users AFTER INSERT ON users REFERENCING (new) AS $$
    INSERT INTO logs (message) VALUES (new.username || ' ' || new.city || ' - ' || new.age || ' years old');
    UPDATE logs SET message = message || ' - ' || new.email;
$$;
"
